def _key(params):
    return json.dumps(params, sort_keys=True, separators=(",", ":"), default=str)


def true10_oracle(params):
    key = _key(params)
    if key not in _TABLE:
        raise KeyError(f"unrecognized true10 scenario parameters: {params!r}")
    return _TABLE[key]


